// Original 4x3 fixtures generated with Pillow/libjpeg; reference values independently decoded by Pillow.
const RGB: &str = "";
const GRAY: &str = "";
const CMYK: &str = "";
const PROGRESSIVE: &str = "";
fn bytes(hex: &str) -> Vec<u8> {
    hex.as_bytes()
        .chunks_exact(2)
        .map(|p| u8::from_str_radix(std::str::from_utf8(p).unwrap(), 16).unwrap())
        .collect()
}
#[test]
fn baseline_progressive_gray_cmyk_match_independent_decoder() {
    for (hex, color) in [
        (RGB, [40_u8, 99, 199]),
        (PROGRESSIVE, [40, 99, 199]),
        (GRAY, [123, 123, 123]),
        (CMYK, [207, 190, 154]),
    ] {
        let image = crate::decode(&bytes(hex), crate::ImageLimits::default()).unwrap();
        assert_eq!((image.width(), image.height()), (4, 3));
        for p in image.pixels().chunks_exact(4) {
            for c in 0..3 {
                assert!(p[c].abs_diff(color[c]) <= 2, "{p:?} vs {color:?}");
            }
            assert_eq!(p[3], 255);
        }
    }
}
#[test]
fn exif_orientation_changes_geometry_consistently() {
    for orientation in 1..=8_u8 {
        let mut tiff =
            b"Exif\0\0II\x2a\0\x08\0\0\0\x01\0\x12\x01\x03\0\x01\0\0\0\x01\0\0\0\0\0\0\0".to_vec();
        tiff[24] = orientation;
        let source = bytes(RGB);
        let mut data = vec![255, 216, 255, 225];
        data.extend_from_slice(&((tiff.len() + 2) as u16).to_be_bytes());
        data.extend_from_slice(&tiff);
        data.extend_from_slice(&source[2..]);
        let image = crate::decode(&data, crate::ImageLimits::default()).unwrap();
        assert_eq!(
            (image.width(), image.height()),
            if orientation >= 5 { (3, 4) } else { (4, 3) }
        );
    }
}
